Operations::Operations(std::shared_ptr<object::Query> query, std::shared_ptr<object::Mutation> mutation)
	: service::Request({
		{ service::strQuery, query },
		{ service::strMutation, mutation }
	}, GetSchema())
	, _query(std::move(query))
	, _mutation(std::move(mutation))
{
}

void AddTypesToSchema(const std::shared_ptr<schema::Schema>& schema)
{
	auto typeMsgType = schema::EnumType::Make(R"gql(MsgType)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(MsgType)gql"sv, typeMsgType);
	auto typeTxStatus = schema::EnumType::Make(R"gql(TxStatus)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(TxStatus)gql"sv, typeTxStatus);
	auto typeTxMode = schema::EnumType::Make(R"gql(TxMode)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(TxMode)gql"sv, typeTxMode);
	auto typeSystemHealth = schema::ObjectType::Make(R"gql(SystemHealth)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(SystemHealth)gql"sv, typeSystemHealth);
	auto typeBusEvent = schema::ObjectType::Make(R"gql(BusEvent)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(BusEvent)gql"sv, typeBusEvent);
	auto typeTemperatureUpdated = schema::ObjectType::Make(R"gql(TemperatureUpdated)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(TemperatureUpdated)gql"sv, typeTemperatureUpdated);
	auto typeGetSystemHealth = schema::ObjectType::Make(R"gql(GetSystemHealth)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(GetSystemHealth)gql"sv, typeGetSystemHealth);
	auto typeHealthReport = schema::ObjectType::Make(R"gql(HealthReport)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(HealthReport)gql"sv, typeHealthReport);
	auto typeDatabaseTx = schema::ObjectType::Make(R"gql(DatabaseTx)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(DatabaseTx)gql"sv, typeDatabaseTx);
	auto typeLogEntry = schema::ObjectType::Make(R"gql(LogEntry)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(LogEntry)gql"sv, typeLogEntry);
	auto typeNotifyEvent = schema::ObjectType::Make(R"gql(NotifyEvent)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(NotifyEvent)gql"sv, typeNotifyEvent);
	auto typeInitFailEvent = schema::ObjectType::Make(R"gql(InitFailEvent)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(InitFailEvent)gql"sv, typeInitFailEvent);
	auto typeQuery = schema::ObjectType::Make(R"gql(Query)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(Query)gql"sv, typeQuery);
	auto typeMutation = schema::ObjectType::Make(R"gql(Mutation)gql"sv, R"md()md"sv);
	schema->AddType(R"gql(Mutation)gql"sv, typeMutation);

	typeMsgType->AddEnumValues({
		{ service::s_namesMsgType[static_cast<size_t>(generated::MsgType::NONE)], R"md()md"sv, std::nullopt },
		{ service::s_namesMsgType[static_cast<size_t>(generated::MsgType::NOTE)], R"md()md"sv, std::nullopt },
		{ service::s_namesMsgType[static_cast<size_t>(generated::MsgType::WARNING)], R"md()md"sv, std::nullopt },
		{ service::s_namesMsgType[static_cast<size_t>(generated::MsgType::ERROR)], R"md()md"sv, std::nullopt },
		{ service::s_namesMsgType[static_cast<size_t>(generated::MsgType::CRITICAL)], R"md()md"sv, std::nullopt },
		{ service::s_namesMsgType[static_cast<size_t>(generated::MsgType::SYS)], R"md()md"sv, std::nullopt }
	});
	typeTxStatus->AddEnumValues({
		{ service::s_namesTxStatus[static_cast<size_t>(generated::TxStatus::WAITING)], R"md()md"sv, std::nullopt },
		{ service::s_namesTxStatus[static_cast<size_t>(generated::TxStatus::FAILED)], R"md()md"sv, std::nullopt },
		{ service::s_namesTxStatus[static_cast<size_t>(generated::TxStatus::SUCCEEDED)], R"md()md"sv, std::nullopt }
	});
	typeTxMode->AddEnumValues({
		{ service::s_namesTxMode[static_cast<size_t>(generated::TxMode::READ)], R"md()md"sv, std::nullopt },
		{ service::s_namesTxMode[static_cast<size_t>(generated::TxMode::WRITE)], R"md()md"sv, std::nullopt }
	});

	AddSystemHealthDetails(typeSystemHealth, schema);
	AddBusEventDetails(typeBusEvent, schema);
	AddTemperatureUpdatedDetails(typeTemperatureUpdated, schema);
	AddGetSystemHealthDetails(typeGetSystemHealth, schema);
	AddHealthReportDetails(typeHealthReport, schema);
	AddDatabaseTxDetails(typeDatabaseTx, schema);
	AddLogEntryDetails(typeLogEntry, schema);
	AddNotifyEventDetails(typeNotifyEvent, schema);
	AddInitFailEventDetails(typeInitFailEvent, schema);
	AddQueryDetails(typeQuery, schema);
	AddMutationDetails(typeMutation, schema);

	schema->AddQueryType(typeQuery);
	schema->AddMutationType(typeMutation);
}

std::shared_ptr<schema::Schema> GetSchema()
{
	static std::weak_ptr<schema::Schema> s_wpSchema;
	auto schema = s_wpSchema.lock();

	if (!schema)
	{
		schema = std::make_shared<schema::Schema>(false, R"md()md"sv);
		introspection::AddTypesToSchema(schema);
		AddTypesToSchema(schema);
		s_wpSchema = schema;
	}

	return schema;
}

